//! Unicode normalization forms NFC, NFD, NFKC and NFKD (UAX #15; Unicode 17 tables in
//! `unicode_norm.txt`, generated by scripts/gen-unicode-norm.py) for
//! `String.prototype.normalize` (ECMA-262 §22.1.3.15).
//!
//! JavaScript strings may hold lone surrogates; they pass through unchanged (they have no
//! decomposition and combining class 0).

use super::fx::HashMap;
use std::sync::OnceLock;

const DATA: &str = include_str!("unicode_norm.txt");

// Hangul syllable constants (Unicode Core Specification §3.12).
const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Form {
    Nfc,
    Nfd,
    Nfkc,
    Nfkd,
}

struct Tables {
    ccc: HashMap<u32, u8>,
    /// Full canonical decompositions (applied recursively at load).
    canon: HashMap<u32, Vec<u32>>,
    /// Full compatibility decompositions (canonical ones included).
    compat: HashMap<u32, Vec<u32>>,
    /// Primary composites: (starter, next) → composite.
    compose: HashMap<(u32, u32), u32>,
}

fn hex(s: &str) -> u32 {
    u32::from_str_radix(s, 16).unwrap_or(0)
}

fn each_cp(ranges: &str, mut f: impl FnMut(u32)) {
    for r in ranges.split(',').filter(|r| !r.is_empty()) {
        match r.split_once('-') {
            Some((a, b)) => (hex(a)..=hex(b)).for_each(&mut f),
            None => f(hex(r)),
        }
    }
}

fn tables() -> &'static Tables {
    static T: OnceLock<Tables> = OnceLock::new();
    T.get_or_init(|| {
        let mut ccc = HashMap::default();
        let mut canon1: HashMap<u32, Vec<u32>> = HashMap::default();
        let mut compat1: HashMap<u32, Vec<u32>> = HashMap::default();
        let mut excl = std::collections::HashSet::new();
        for line in DATA.lines() {
            let mut p = line.splitn(3, ' ');
            match (p.next(), p.next(), p.next()) {
                (Some("C"), Some(k), Some(rs)) => {
                    let k: u8 = k.parse().unwrap_or(0);
                    each_cp(rs, |c| {
                        ccc.insert(c, k);
                    });
                }
                (Some("D"), Some(cp), Some(seq)) => {
                    canon1.insert(hex(cp), seq.split('_').map(hex).collect());
                }
                (Some("K"), Some(cp), Some(seq)) => {
                    compat1.insert(hex(cp), seq.split('_').map(hex).collect());
                }
                (Some("X"), Some(rs), None) => each_cp(rs, |c| {
                    excl.insert(c);
                }),
                _ => {}
            }
        }
        // Full decompositions: apply the mappings until nothing changes (D68, D65).
        fn full(c: u32, one: &dyn Fn(u32) -> Option<Vec<u32>>, out: &mut Vec<u32>) {
            match one(c) {
                Some(d) => d.into_iter().for_each(|x| full(x, one, out)),
                None => out.push(c),
            }
        }
        let canon_one = |c: u32| canon1.get(&c).cloned();
        let compat_one = |c: u32| compat1.get(&c).cloned().or_else(|| canon1.get(&c).cloned());
        let mut canon = HashMap::default();
        for &c in canon1.keys() {
            let mut v = Vec::new();
            full(c, &canon_one, &mut v);
            canon.insert(c, v);
        }
        let mut compat = HashMap::default();
        for &c in canon1.keys().chain(compat1.keys()) {
            let mut v = Vec::new();
            full(c, &compat_one, &mut v);
            compat.insert(c, v);
        }
        // Primary composites: canonical mappings of two code points, not excluded (D114).
        let mut compose = HashMap::default();
        for (&c, d) in &canon1 {
            if d.len() == 2 && !excl.contains(&c) {
                compose.insert((d[0], d[1]), c);
            }
        }
        Tables { ccc, canon, compat, compose }
    })
}

fn ccc(t: &Tables, c: u32) -> u8 {
    t.ccc.get(&c).copied().unwrap_or(0)
}

/// Code points of a UTF-16 string; lone surrogates stay as themselves.
fn code_points(s: &[u16]) -> Vec<u32> {
    char::decode_utf16(s.iter().copied())
        .map(|r| r.map(|c| c as u32).unwrap_or_else(|e| e.unpaired_surrogate() as u32))
        .collect()
}

fn decompose(t: &Tables, cps: &[u32], compat: bool) -> Vec<u32> {
    let mut out = Vec::with_capacity(cps.len());
    for &c in cps {
        if (S_BASE..S_BASE + S_COUNT).contains(&c) {
            let s = c - S_BASE;
            out.push(L_BASE + s / N_COUNT);
            out.push(V_BASE + (s % N_COUNT) / T_COUNT);
            if s % T_COUNT != 0 {
                out.push(T_BASE + s % T_COUNT);
            }
            continue;
        }
        let m = if compat { t.compat.get(&c) } else { t.canon.get(&c) };
        match m {
            Some(d) => out.extend_from_slice(d),
            None => out.push(c),
        }
    }
    // Canonical Ordering Algorithm (D109): a stable sort of each run of non-starters.
    let mut i = 0;
    while i < out.len() {
        if ccc(t, out[i]) == 0 {
            i += 1;
            continue;
        }
        let start = i;
        while i < out.len() && ccc(t, out[i]) != 0 {
            i += 1;
        }
        out[start..i].sort_by_key(|&c| ccc(t, c));
    }
    out
}

/// Canonical Composition Algorithm (D117). In canonical order, a character is blocked from
/// the last starter when something in between has combining class 0 or ≥ its own, and the
/// last character in between has the highest class of them (D115).
fn compose(t: &Tables, cps: &mut Vec<u32>) {
    let mut out: Vec<u32> = Vec::with_capacity(cps.len());
    let mut starter: Option<usize> = None;
    // The combining class of the last character after the starter, if any.
    let mut last: Option<u8> = None;
    for &c in cps.iter() {
        let cc = ccc(t, c);
        if let Some(si) = starter {
            if !last.is_some_and(|l| l == 0 || l >= cc) {
                if let Some(p) = pair(t, out[si], c) {
                    out[si] = p;
                    continue;
                }
            }
        }
        if cc == 0 {
            starter = Some(out.len());
            last = None;
        } else {
            last = Some(cc);
        }
        out.push(c);
    }
    *cps = out;
}

/// The primary composite of `a` and `b`, Hangul included.
fn pair(t: &Tables, a: u32, b: u32) -> Option<u32> {
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        return Some(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a)
        && (a - S_BASE) % T_COUNT == 0
        && (T_BASE + 1..T_BASE + T_COUNT).contains(&b)
    {
        return Some(a + (b - T_BASE));
    }
    t.compose.get(&(a, b)).copied()
}

/// `s` in normalization form `form`, as UTF-16.
pub fn normalize(s: &[u16], form: Form) -> Vec<u16> {
    let t = tables();
    let compat = matches!(form, Form::Nfkc | Form::Nfkd);
    let mut cps = decompose(t, &code_points(s), compat);
    if matches!(form, Form::Nfc | Form::Nfkc) {
        compose(t, &mut cps);
    }
    let mut out = Vec::with_capacity(cps.len());
    for c in cps {
        match char::from_u32(c) {
            Some(ch) => out.extend_from_slice(ch.encode_utf16(&mut [0; 2])),
            None => out.push(c as u16),
        }
    }
    out
}
